import { JoseSessionTokens } from "./session-tokens.ts";

// The construction runs at plan time as well as when the isolate starts, and
// the bindings only exist in the second. So the app, with every layer that
// reads D1, is built inside `fetch`, once per request.
export default class Api extends Cloudflare.Worker<Api>()(
  "Api",
  {
    main: import.meta.url,
    dev: { port: 1337 },
  },
  Effect.gen(function* () {
    const database = yield* KurasuDatabase;
    const d1 = yield* Cloudflare.D1.QueryDatabase(database);

    const bucket = yield* Cloudflare.R2.ReadWriteBucket(MaterialsBucket);
    const aulas = yield* Aula;

    const domain = yield* Config.String("KURASU_DOMAIN").pipe(
      Config.withDefault("kurasu.asermax.com"),
    );

    // Where the links of the mail and the QR point. Deployed it is the domain;
    // under `alchemy dev` it is the local web, set in .env.schema.
    const webOrigin = yield* Config.String("KURASU_WEB_ORIGIN").pipe(
      Config.withDefault(`https://${domain}`),
    );

    const jwtSecret = REDACTED Config.Redacted("JWT_SECRET");
    const sender = `no-reply@${domain}`;
    const email = yield* Cloudflare.Email.Send(yield* mailBinding(sender));

    const stores = Layer.mergeAll(
      D1Users,
      D1Codes,
      D1Sessions,
      D1Polls,
      D1Responses,
      D1Materials,
      D1Questions,
      D1QuestionVotes,
      D1Hands,
      D1Changelog,
      D1Batch,
    ).pipe(Layer.provide(Database.layer(d1.raw)));

    const platform = Layer.mergeAll(
      EmailSendingMailer(email, sender),
      JoseSessionTokens(jwtSecret),
      WebCrypto,
      R2Files(bucket),
      DurableObjectClassroom(aulas),
    );

    const services = Layer.mergeAll(
      Access.layer(webOrigin),
      Announcements.layer(webOrigin).pipe(Layer.provideMerge(Sessions.layer)),
      Polls.layer,
      Materials.layer,
      Questions.layer,
      Hands.layer,
    ).pipe(
      Layer.provideMerge(Changelog.layer),
      Layer.provideMerge(stores),
      Layer.provideMerge(platform),
    );

    const app = HttpApiBuilder.layer(KurasuApi).pipe(
      Layer.provide([
        AuthHandlers,
        MeHandlers,
        AdminUsersHandlers(webOrigin),
        SessionsHandlers,
        AdminSessionsHandlers,
        PollsHandlers,
        AdminPollsHandlers,
        MaterialsHandlers,
        AdminMaterialsHandlers,
        AdminChangelogHandlers,
        AdminAnnouncementsHandlers,
        QuestionsHandlers,
        AdminQuestionsHandlers,
        RaisedHandsHandlers,
        AdminRaisedHandsHandlers,
        ClassroomHandlers(aulas),
      ]),
      Layer.provide(CurrentUserMiddlewareLive),
      Layer.provide(services),
      Layer.provide(HttpServer.layerServices),
    );

import * as Cloudflare from "@alchemy.run/cloudflare";
import * as Output from "alchemy/Output";
import * as Effect from "effect/Effect";

import { kurasuDomain } from "./domain.ts";

const rootDir = new URL("../../web", import.meta.url).pathname;

const baseProps = {
  rootDir,
  assets: { notFoundHandling: "single-page-application" },
  dev: { port: 5173 },
} as const;

// The web's own Worker: the TanStack Start SPA and its assets. It takes the
// custom domain only when deployed; under `alchemy dev` it is the Vite dev
// server. Alchemy hands the dev server only the `VITE_` env entries, as
// `define`s, so that is how vite.config.ts learns which URL the API Worker
// ended up on.
export const Web = (apiUrl: Output.Output<string | undefined>) =>
  Cloudflare.Website.Vite(
    "Web",
    Effect.map(Effect.orDie(kurasuDomain), (domain) =>
      domain.deployed
        ? { ...baseProps, domain: domain.name }
        : { ...baseProps, env: { VITE_API_URL: Output.map(apiUrl, (url) => url ?? "") } },
    ),
  );

