// usage: node ws-listen.mjs <jar> <sessionId> <label>
import { readFileSync } from "node:fs";

const [jar, sessionId, label] = process.argv.slice(2);
const line = readFileSync(jar, "utf8").split("\n").find((l) => l.includes("\t") && !l.startsWith("# "));
const parts = line.split("\t");
const cookie = `${parts[5]}=${parts[6]}`;
const ws = new WebSocket(`ws://localhost:5173/api/classroom?sessionId=${sessionId}`, { headers: { cookie } });

ws.onopen = () => console.log(new Date().toISOString(), label, "open");
ws.onmessage = (e) => console.log(new Date().toISOString(), label, e.data);
ws.onerror = (e) => console.log(new Date().toISOString(), label, "error", e.message ?? "");
ws.onclose = (e) => console.log(new Date().toISOString(), label, "close", e.code, e.reason);

